"""Exercise the release render command with mocked filesystem boundaries."""
from pathlib import Path
import unittest
from unittest.mock import MagicMock, patch

import bundle_helpers
from test_compose_rendering import COMPOSE_SOURCE


class BundleRenderCommandTest(unittest.TestCase):
    # Generated by Codex and not thoroughly checked for correctness.
    def test_reads_backend_manifest_and_writes_image_only_release_compose(self):
        root = MagicMock(spec=Path)
        output = MagicMock(spec=Path)
        backend = root.__truediv__.return_value
        source = backend.__truediv__.return_value
        source.read_text.return_value = COMPOSE_SOURCE
        destination = output.__truediv__.return_value

        with patch.object(bundle_helpers, "Path", side_effect={
            "/repo": root, "/bundle": output,
        }.__getitem__), patch("sys.argv", [
            "bundle_helpers.py", "render-compose", "/repo", "/bundle", "release-001",
        ]):
            bundle_helpers.main()

        root.__truediv__.assert_called_once_with("backend")
        backend.__truediv__.assert_called_once_with("compose.production.yml")
        source.read_text.assert_called_once_with()
        output.__truediv__.assert_called_once_with("compose.yml")
        rendered = destination.write_text.call_args.args[0]
        self.assertNotIn("    build:", rendered)
        self.assertIn("image: cftracker-backend:release-001", rendered)
        self.assertIn("image: cftracker-migration:release-001", rendered)
        self.assertIn("/etc/cftracker/init-app-role.sql:", rendered)
